def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0

    players_alive = 1 + len(alive_opponents)
    supply_units = float(supply) / float(WATER_REQ)
    scarcity = supply_units < players_alive

    highest_prev_bid = 0
    aggressive_count = 0
    desperate_count = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            if bid > highest_prev_bid:
                highest_prev_bid = bid
            if bid >= DAILY_SALARY * 0.8:
                aggressive_count += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1

    if hp <= 2 or no_water_days >= 2:
        target = DAILY_SALARY * 0.96
    elif hp <= 4 or no_water_days >= 1:
        target = DAILY_SALARY * 0.82
    else:
        if scarcity:
            target = DAILY_SALARY * 0.58
            if highest_prev_bid > 0:
                target = max(target, highest_prev_bid + 1.25)
            if aggressive_count >= max(1, len(alive_opponents) // 2):
                target = max(target, DAILY_SALARY * 0.72)
            if desperate_count >= 2:
                target = max(target, DAILY_SALARY * 0.76)
        else:
            target = DAILY_SALARY * 0.28
            if highest_prev_bid >= DAILY_SALARY * 0.75:
                target = DAILY_SALARY * 0.18

    if budget < target:
        return budget
    return max(0, target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15
    budget = my_status['budget']
    hp = my_status['hp']
    no_water_days = my_status['no_water_days']
    # Desperation: if you've missed water for 2+ days or very low HP, bid high
    if hp <= 2 or no_water_days >= 2:
        return min(budget, DAILY_SALARY * 1.2)
    # Gather yesterday's bids from alive opponents
    prev_bids = []
    for opp in opponents_status.values():
        if opp['alive']:
            pt = opp.get('previous_trace')
            if pt and pt.get('bid') is not None:
                prev_bids.append(pt['bid'])
    # If we have information about yesterday's highest bid
    if prev_bids:
        max_prev = max(prev_bids)
        # If opponents were very aggressive last day, be conservative if healthy
        if max_prev >= DAILY_SALARY * 0.85:
            if hp > 3:
                return min(budget, DAILY_SALARY * 0.35)
            else:
                return min(budget, DAILY_SALARY * 0.9)
        else:
            # Slightly beat the highest previous bid but cap at budget
            return min(budget, max(DAILY_SALARY * 0.5, max_prev + 2.0))
    # No history: moderate bid based on HP
    if hp <= 4:
        return min(budget, DAILY_SALARY * 0.8)
    else:
        return min(budget, DAILY_SALARY * 0.6)
